#include <stdlib.h>
typedef struct Node { int v; struct Node *next; } Node;

Node *push(Node *head, int v) {
    Node *n = malloc(sizeof *n);
    n->v = v; n->next = head;
    return n;
}
Node *reverse(Node *head) {
    // reverse the list in place by re-pointing each next; return the new head
    return head;
}
void print(Node *h) { for (; h; h = h->next) printf("%d%c", h->v, h->next ? ' ' : '\n'); }
int main(void) {
    Node *h = NULL;
    for (int i = 1; i <= 4; i++) h = push(h, i);
    print(h);
    h = reverse(h);
    print(h);
    while (h) { Node *n = h->next; free(h); h = n; }
    return 0;
}

challenges.solution:
#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int v; struct Node *next; } Node;

Node *push(Node *head, int v) {
    Node *n = malloc(sizeof *n);
    n->v = v; n->next = head;
    return n;
}
Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}
void print(Node *h) { for (; h; h = h->next) printf("%d%c", h->v, h->next ? ' ' : '\n'); }
int main(void) {
    Node *h = NULL;
    for (int i = 1; i <= 4; i++) h = push(h, i);
    print(h);
    h = reverse(h);
    print(h);
    while (h) { Node *n = h->next; free(h); h = n; }
    return 0;
}

